using System;using System.IO;using System.Linq;using System.Globalization;using System.Collections.Generic;
namespace FileCompass {
 internal static partial class MediaAudio {
  internal static double SourceDuration(MediaAudioOptions options,MediaInfo info){if(options.Track<0||options.Track>=info.Audio.Count)throw new IOException(L.Text("media.trackMissing"));return info.Audio[options.Track].Duration>0?info.Audio[options.Track].Duration:info.Duration;}
  internal static double SpeedFactor(MediaAudioOptions options,MediaInfo info){double speed=options.Speed;if(Double.IsNaN(speed)||Double.IsInfinity(speed)||speed<.1||speed>10||Double.IsNaN(options.TargetDurationSeconds)||Double.IsInfinity(options.TargetDurationSeconds)||options.TargetDurationSeconds<0)throw new IOException(L.Text("media.speedInvalid"));if(options.TargetDurationSeconds>0){double duration=SourceDuration(options,info);if(duration<=0||Double.IsNaN(duration)||Double.IsInfinity(duration))throw new IOException(L.Text("media.durationMissing"));speed=duration/options.TargetDurationSeconds;}if(speed<.1||speed>10||Double.IsNaN(speed)||Double.IsInfinity(speed))throw new IOException(L.Text("media.speedInvalid"));return speed;}
  internal static List<string> SpeedFilters(MediaAudioOptions options,MediaInfo info,int rate){double factor=SpeedFactor(options,info);var filters=new List<string>();if(Math.Abs(factor-1)>1e-9){if(options.PreservePitch){while(factor>2){filters.Add("atempo=2");factor/=2;}while(factor<.5){filters.Add("atempo=0.5");factor/=.5;}if(Math.Abs(factor-1)>1e-9)filters.Add("atempo="+factor.ToString("R",CultureInfo.InvariantCulture));}else{int input=info.Audio[options.Track].SampleRate;if(input<=0)throw new IOException(L.Text("media.sampleUnsupported"));filters.Add("asetrate="+Math.Round(input*factor,MidpointRounding.AwayFromZero).ToString(CultureInfo.InvariantCulture));filters.Add("aresample="+rate.ToString(CultureInfo.InvariantCulture));}}if(options.TargetDurationSeconds>0){string duration=options.TargetDurationSeconds.ToString("R",CultureInfo.InvariantCulture);filters.Add("apad=whole_dur="+duration);filters.Add("atrim=duration="+duration);}return filters;}
 }
 internal static class AudioTempo {
  internal static readonly double[] Factors={1,25.0*1001/24000,25.0/24,24000.0/(1001*25),24.0/25,1001.0/1000,1000.0/1001,.5,.75,1.25,1.5,2,1,1};
  internal static double ParseDuration(string text){string[] fields=(text??"").Trim().Replace(',','.').Split(':');double seconds;if(fields.Length==1){if(!Double.TryParse(fields[0],NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out seconds))throw new IOException(L.Text("media.durationInvalid"));}else if(fields.Length==2||fields.Length==3){double tail;int minutes,hours=0;if(!Double.TryParse(fields[fields.Length-1],NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out tail)||tail>=60||!Int32.TryParse(fields[fields.Length-2],NumberStyles.None,CultureInfo.InvariantCulture,out minutes)||fields.Length==3&&(minutes>=60||!Int32.TryParse(fields[0],NumberStyles.None,CultureInfo.InvariantCulture,out hours)))throw new IOException(L.Text("media.durationInvalid"));seconds=hours*3600.0+minutes*60.0+tail;}else throw new IOException(L.Text("media.durationInvalid"));if(seconds<=0||seconds>7*86400||Double.IsInfinity(seconds)||Double.IsNaN(seconds))throw new IOException(L.Text("media.durationInvalid"));return seconds;}
  internal static string Duration(double seconds){if(seconds<0||Double.IsInfinity(seconds)||Double.IsNaN(seconds))return "—";var span=TimeSpan.FromSeconds(seconds);return ((long)span.TotalHours).ToString("D2",CultureInfo.InvariantCulture)+span.ToString(@"\:mm\:ss\.fff",CultureInfo.InvariantCulture);}
 }
}
